UPDATE public.health_examination_batch_participants AS target SET participant_code_snapshot = source.participant_code_snapshot, department_snapshot = source.department_snapshot, job_title_snapshot = source.job_title_snapshot, occupation_snapshot = source.occupation_snapshot, full_name_snapshot = source.full_name_snapshot, date_of_birth_snapshot = source.date_of_birth_snapshot, sex_snapshot = source.sex_snapshot, identification_number_snapshot = source.identification_number_snapshot, identification_number_issue_date_snapshot = source.identification_number_issue_date_snapshot, identification_number_issue_place_snapshot = source.identification_number_issue_place_snapshot, ethnicity_snapshot = source.ethnicity_snapshot, subject_type_snapshot = source.subject_type_snapshot, payer_source_snapshot = source.payer_source_snapshot, blood_group_snapshot = source.blood_group_snapshot, phone_snapshot = source.phone_snapshot, province_snapshot = source.province_snapshot, ward_snapshot = source.ward_snapshot, address_detail_snapshot = source.address_detail_snapshot, administrative_occupation_snapshot = source.administrative_occupation_snapshot, workplace_or_school_snapshot = source.workplace_or_school_snapshot, health_examination_reason_snapshot = source.health_examination_reason_snapshot, roster_note_snapshot = source.roster_note_snapshot FROM (VALUES
(#{item.id}, #{batchId}, #{item.healthExaminationParticipantId}, #{item.participantCodeSnapshot}, #{item.departmentSnapshot}, #{item.jobTitleSnapshot}, #{item.occupationSnapshot}, #{item.fullNameSnapshot}, #{item.dateOfBirthSnapshot}, #{item.sexSnapshot}, #{item.identificationNumberSnapshot}, CAST(#{item.identificationNumberIssueDateSnapshot} AS date), #{item.identificationNumberIssuePlaceSnapshot}, #{item.ethnicitySnapshot}, #{item.subjectTypeSnapshot}, #{item.payerSourceSnapshot}, #{item.bloodGroupSnapshot}, #{item.phoneSnapshot}, #{item.provinceSnapshot}, #{item.wardSnapshot}, #{item.addressDetailSnapshot}, #{item.administrativeOccupationSnapshot}, #{item.workplaceOrSchoolSnapshot}, #{item.healthExaminationReasonSnapshot}, #{item.rosterNoteSnapshot})
) AS source(id, batch_id, participant_id, participant_code_snapshot, department_snapshot, job_title_snapshot, occupation_snapshot, full_name_snapshot, date_of_birth_snapshot, sex_snapshot, identification_number_snapshot, identification_number_issue_date_snapshot, identification_number_issue_place_snapshot, ethnicity_snapshot, subject_type_snapshot, payer_source_snapshot, blood_group_snapshot, phone_snapshot, province_snapshot, ward_snapshot, address_detail_snapshot, administrative_occupation_snapshot, workplace_or_school_snapshot, health_examination_reason_snapshot, roster_note_snapshot) WHERE target.id = source.id AND target.health_examination_batch_id = source.batch_id AND target.health_examination_participant_id = source.participant_id
